-- Forward sensitive-source guard and caller-RLS question projection.
create or replace function public.save_catalog_question_draft(p_question_id uuid,p_source_version_id uuid,p_scope text,p_payload jsonb,p_change_reason text,p_expected_identity_row_version integer,p_expected_source_row_version integer,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid()) returns jsonb
language plpgsql security definer set search_path=pg_catalog,extensions,private as $$
declare v_actor uuid:=auth.uid();v_identity public.question_bank_questions%rowtype;v_source public.question_versions%rowtype;v_hash text;v_command uuid;v_replay jsonb;v_number integer;v_version uuid;v_org uuid;v_response jsonb;
begin
 if v_actor is null or p_expected_identity_row_version<1 or p_expected_source_row_version<1 then raise exception 'INVALID_CATALOG_QUESTION' using errcode='22023';end if;select * into v_identity from public.question_bank_questions where id=p_question_id;if not found or not private.has_library_permission(v_identity.library_id,'CATALOG_EDIT',v_actor)then raise exception 'CATALOG_SCOPE_DENIED' using errcode='42501';end if;perform private.assert_question_builder_payload(v_identity.library_id,p_scope,p_payload);select * into v_source from public.question_versions where id=p_source_version_id and question_id=p_question_id;if not found then raise exception 'CATALOG_QUESTION_VERSION_NOT_FOUND' using errcode='P0002';end if;
 if p_scope='GLOBAL'or v_identity.scope='GLOBAL'then perform private.assert_catalog_central_aal2_locked(v_actor);end if;if(v_source.sensitivity in('CONFIDENTIAL','RESTRICTED')or p_payload->>'sensitivity'in('CONFIDENTIAL','RESTRICTED'))and auth.jwt()->>'aal'is distinct from'aal2'then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED' using errcode='42501';end if;
 v_hash:=private.canonical_request_hash(jsonb_build_object('operation','catalog.question.save.v1','question_id',p_question_id,'source_version_id',p_source_version_id,'scope',p_scope,'payload',p_payload,'change_reason',btrim(p_change_reason),'expected_identity',p_expected_identity_row_version,'expected_source',p_expected_source_row_version));select b.command_id,b.response_body into v_command,v_replay from private.begin_catalog_command(v_actor,'catalog.question.save',p_idempotency_key,v_hash)b;
 perform pg_advisory_xact_lock(hashtextextended('catalog-question:'||p_question_id::text,0));select * into v_identity from public.question_bank_questions where id=p_question_id for update;select * into v_source from public.question_versions where id=p_source_version_id and question_id=p_question_id for share;perform private.assert_catalog_permission_locked(v_identity.library_id,'CATALOG_EDIT',v_actor);if p_scope='GLOBAL'or v_identity.scope='GLOBAL'then perform private.assert_catalog_central_aal2_locked(v_actor);end if;if(v_source.sensitivity in('CONFIDENTIAL','RESTRICTED')or p_payload->>'sensitivity'in('CONFIDENTIAL','RESTRICTED'))and auth.jwt()->>'aal'is distinct from'aal2'then raise exception 'CATALOG_SENSITIVE_MFA_REQUIRED'using errcode='42501';end if;if v_replay is not null then return v_replay;end if;if v_identity.status='ARCHIVED'or p_source_version_id is distinct from coalesce(v_identity.current_draft_version_id,v_identity.current_published_version_id)then raise exception 'CATALOG_QUESTION_NOT_EDITABLE' using errcode='55000';end if;if v_identity.row_version is distinct from p_expected_identity_row_version or v_source.row_version is distinct from p_expected_source_row_version then raise exception 'STALE_CATALOG_VERSION' using errcode='40001';end if;
 select coalesce(max(version),0)+1 into v_number from public.question_versions where question_id=p_question_id;v_version:=private.insert_question_builder_version(p_question_id,v_identity.library_id,p_payload,p_change_reason,v_actor,v_number);select steward_organization_id into v_org from public.catalog_libraries where id=v_identity.library_id;update public.question_bank_questions set scope=p_scope,status=case when current_published_version_id is null then'DRAFT'else'PUBLISHED'end,current_draft_version_id=v_version,row_version=row_version+1 where id=p_question_id;
 v_response:=jsonb_build_object('outcome','CATALOG_QUESTION_DRAFT_SAVED','question_id',p_question_id,'library_id',v_identity.library_id,'version_id',v_version,'version_number',v_number,'identity_row_version',p_expected_identity_row_version+1,'version_row_version',1,'content_hash',private.canonical_request_hash(p_payload),'command_id',v_command);
 insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,previous_hash,event_hash)values(v_org,v_actor,'USER','catalog.question.draft_saved','catalog_question',p_question_id::text,p_correlation_id,jsonb_build_object('source_version_id',p_source_version_id,'version_id',v_version,'command_id',v_command),v_source.content_hash,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key,causation_id)values(v_org,'catalog_question',p_question_id::text,'CatalogQuestionDraftSavedV1',p_correlation_id,jsonb_build_object('question_id',p_question_id,'version_id',v_version),p_idempotency_key,v_command);perform private.finish_catalog_command(v_actor,'catalog.question.save',p_idempotency_key,v_response);return v_response;
end $$;


create function public.franchise_question_detail(p_franchise_id uuid,p_question_id uuid)returns jsonb
language plpgsql stable security invoker set search_path=pg_catalog as $$
declare result jsonb;
begin
 if not public.franchise_catalog_scope(p_franchise_id)then raise exception 'FRANCHISE_CATALOG_SCOPE_DENIED'using errcode='42501';end if;
 select jsonb_build_object('id',q.id,'libraryId',q.library_id,'key',q.question_key,'scope',q.scope,'identityStatus',q.status,'identityRowVersion',q.row_version,'versionId',v.id,'version',v.version,'versionStatus',v.status,'versionRowVersion',v.row_version,'payload',
 jsonb_build_object('label_fr',v.label_fr,'label_ar',v.label_ar,'help_fr',v.help_fr,'help_ar',v.help_ar,'why_we_ask_fr',v.why_we_ask_fr,'why_we_ask_ar',v.why_we_ask_ar,'answer_type',v.answer_type,'data_key',v.data_key,'required_by_default',v.required_by_default,'required_for_quote',v.required_for_quote,'required_for_publication',v.required_for_publication,'options',v.options,'validation_schema',v.validation_schema,'structured_schema',v.structured_schema,'visibility_rule',v.visibility_rule,'default_value',v.default_value,'prefill_source',v.prefill_source,'sensitivity',v.sensitivity,'nullable',v.nullable,'weight',v.weight,'maximum_score',v.maximum_score,'template_key',v.template_key,'source_service_id',v.source_service_id)||case when v.validity_interval is null then'{}'::jsonb else jsonb_build_object('validity_seconds',extract(epoch from v.validity_interval))end)into result
 from public.question_bank_questions q join public.question_versions v on v.id=coalesce(q.current_draft_version_id,q.current_published_version_id)join public.franchises f on f.library_id=q.library_id where f.id=p_franchise_id and q.id=p_question_id;
 if result is null then raise exception 'FRANCHISE_CATALOG_SCOPE_DENIED'using errcode='42501';end if;
 return result;
end$$;
revoke all on function public.franchise_question_detail(uuid,uuid)from public,anon,service_role;
grant execute on function public.franchise_question_detail(uuid,uuid)to authenticated;
